const SPACING=6;
const STEP=1/120;
const DRAG=1.45;
export const MAX_PARTICLES=220;
export const MAX_PARTICLE_LIFETIME=1.3;

export function particleOpacity(particle) {
  const t=Math.max(0,Math.min(1,(particle.age-.04)/(particle.duration-.04)));
  const appear=Math.min(1,particle.age/.055);
  return appear*appear*(3-2*appear)*(1-t*t*(3-2*t));
}

export function createCursorFlow() {
  return {particles:[],x:0,y:0,headX:0,headY:0,positioned:false,continuous:false,cursorVisible:false,interactive:false,seed:0,remainder:0,accumulator:0};
}

function emitParticle(flow,x,y,tx=0,ty=0,speed=0) {
  const phase=++flow.seed*2.399963;
  const side=Math.sin(phase*1.7);
  const offset=side*(4+Math.min(speed*.006,5));
  const backward=Math.min(320,55+speed*.28)*(.65+(Math.cos(phase)+1)*.3);
  const spread=side*(38+Math.min(speed*.09,85));
  flow.particles.push({
    x:x-ty*offset,y:y+tx*offset,
    vx:-tx*backward-ty*spread,vy:-ty*backward+tx*spread-5,
    curl:Math.sin(phase*.7)*.75,
    age:0,duration:.85+(Math.sin(phase*1.3)+1)*.225,
    size:.55+(Math.cos(phase*1.4)+1)*.4,
    brightness:.4+(Math.sin(phase*2.3)+1)*.23,
  });
}

export function moveCursorFlow(flow,x,y,emit=true) {
  if(!emit){
    flow.particles.length=0;flow.remainder=0;flow.accumulator=0;
    flow.headX=x;flow.headY=y;
  }else if(!flow.positioned || !flow.continuous){
    flow.headX=x;flow.headY=y;flow.remainder=0;
    emitParticle(flow,x,y);
  }
  flow.x=x;flow.y=y;flow.positioned=true;flow.continuous=true;
}

export function endCursorFlow(flow) {
  flow.cursorVisible=false;flow.continuous=false;
}

export function advanceCursorFlow(flow,delta) {
  const dt=Math.max(0,delta);
  // Expired frames must not replay an old stroke after a background tab resumes.
  if(dt>=MAX_PARTICLE_LIFETIME){
    flow.particles.length=0;flow.headX=flow.x;flow.headY=flow.y;
    flow.remainder=0;flow.accumulator=0;
    return false;
  }
  flow.accumulator+=dt;
  while(flow.accumulator+1e-9>=STEP){
    const decay=Math.exp(-DRAG*STEP),travel=(1-decay)/DRAG;
    for(const particle of flow.particles){
      particle.x+=particle.vx*travel;particle.y+=particle.vy*travel;
      const angle=particle.curl*STEP,cos=Math.cos(angle),sin=Math.sin(angle);
      const vx=particle.vx,vy=particle.vy;
      particle.vx=(vx*cos-vy*sin)*decay;
      particle.vy=(vx*sin+vy*cos)*decay;particle.age+=STEP;
    }
    flow.particles=flow.particles.filter(particle=>particle.age<particle.duration);
    if(flow.positioned && flow.continuous){
      // A softly following emitter gives the wake a pulled, elastic origin.
      const follow=1-Math.exp(-STEP/.085);
      const dx=(flow.x-flow.headX)*follow,dy=(flow.y-flow.headY)*follow;
      const distance=Math.hypot(dx,dy);
      if(distance>.025){
        const amount=Math.floor((flow.remainder+distance)/SPACING);
        const count=Math.min(36,amount),first=SPACING-flow.remainder;
        for(let i=0;i<count;i++){
          const t=amount>36?(i+.5)/count:(first+i*SPACING)/distance;
          emitParticle(flow,flow.headX+dx*t,flow.headY+dy*t,dx/distance,dy/distance,distance/STEP);
        }
        flow.remainder=(flow.remainder+distance)%SPACING;
        flow.headX+=dx;flow.headY+=dy;
      }else{flow.headX=flow.x;flow.headY=flow.y;}
    }
    if(flow.particles.length>MAX_PARTICLES)flow.particles.splice(0,flow.particles.length-MAX_PARTICLES);
    flow.accumulator-=STEP;
  }
  return flow.particles.length>0 || (flow.positioned && flow.continuous && Math.hypot(flow.x-flow.headX,flow.y-flow.headY)>.1);
}
